def _existing_result(request):
    erp_service = _text(getattr(request, "erp_service", None))
    erp_task = _text(getattr(request, "erp_task", None))
    if not erp_service or not erp_task:
        return None
    if not frappe.db.exists("Service", erp_service) or not frappe.db.exists("Task", erp_task):
        return None
    return {
        "status": "Synced",
        "erp_customer": _text(getattr(request, "erp_customer", None)),
        "erp_service": erp_service,
        "erp_task": erp_task,
        "task_assignment": None,
        "created": False,
    }

